Wartezimmer wartezimmer = new Warteschlange();             // Aufgabe 5

println("--- Fünf Patienten kommen ---");
wartezimmer.add(new Patient("Hans", "Husten"));
wartezimmer.add(new Patient("Vroni", "Fieber"));
wartezimmer.add(new Patient("Schorsch", "Erkältung"));
wartezimmer.add(new Patient("Resi", "Grippe"));
wartezimmer.add(new Patient("Bene", "Kopfweh"));
wartezimmer.ausgeben();

println("--- Die Ärztin ruft drei auf ---");
for (int i = 0; i < 3; i++) {
   Patient p = wartezimmer.poll();
   if (p != null) {
      println("Aufgerufen: " + p.getName());
   }
}

println("--- Vier neue kommen ---");
wartezimmer.add(new Patient("Gustav", "Rückenweh"));
wartezimmer.add(new Patient("Leonie", "Ausschlag"));
wartezimmer.add(new Patient("Ludwig", "Bauchweh"));
wartezimmer.add(new Patient("Mia", "Halsweh"));
wartezimmer.ausgeben();

println("--- Die Ärztin ruft alle auf ---");
for (int i = 0; i < 7; i++) {
   Patient p = wartezimmer.poll();
   if (p != null) {
      println("Aufgerufen: " + p.getName());
   }
}

/**
 * Warteschlange (Queue) aus verketteten Knoten.
 * Suche (Strg + F) nach "TODO" und ergänze den Code.
 */
public class Warteschlange implements Wartezimmer {
   private Knoten anfang;   // erster Knoten: wird als Nächstes aufgerufen
   private Knoten ende;     // letzter Knoten: hier wird angehängt

   public Warteschlange() {
      anfang = null;        // Am Anfang ist die Schlange leer.
      ende = null;
   }

   // Gibt true zurück, wenn niemand wartet.
   public boolean isEmpty() {
      return anfang == null;
   }

   // Stellt p hinten an. Gibt true zurück, wenn das geklappt hat.
   public boolean add(Patient p) {
      Knoten neu = new Knoten(p);      // ①
      if (isEmpty()) {                 // Sonderfall: leere Schlange
         anfang = neu;
         ende = neu;
      } else {
         ende.setNachfolger(neu);      // ②
         ende = neu;                   // ③
      }
      return true;
   }

   // Holt den vordersten Patienten heraus und gibt ihn zurück (null, wenn leer).
   public Patient poll() {
      if (isEmpty()) {
         return null;                        // niemand wartet
      } else {
         Patient p = anfang.getDaten();      // ①
         anfang = anfang.getNachfolger();    // ②
         if (anfang == null) {               // ③
            ende = null;
         }
         return p;                           // ④
      }
   }

   // Gibt den vordersten Patienten zurück, ohne ihn herauszuholen (null, wenn leer).
   public Patient peek() {
      if (isEmpty()) {
         return null;
      } else {
         return anfang.getDaten();
      }
   }

   // Gibt die Anzahl der Wartenden zurück (Selbst bauen b).
   public int anzahl() {
      int zaehler = 0;
      Knoten aktuell = anfang;
      while (aktuell != null) {
         zaehler++;
         aktuell = aktuell.getNachfolger();
      }
      return zaehler;
   }

   // Durchläuft die Kette vom Anfang bis zum Ende und gibt alle Wartenden aus.
   public void ausgeben() {
      Knoten aktuell = anfang;
      int platz = 1;
      while (aktuell != null) {
         println("  " + platz + ". " + aktuell.getDaten().getName());
         aktuell = aktuell.getNachfolger();
         platz++;
      }
   }
}

/**
 * Ein Knoten der Warteschlange: kennt seine Daten und seinen Nachfolger.
 * Muss nicht verändert werden.
 */
public class Knoten {
   private Patient daten;
   private Knoten nachfolger;   // Referenzattribut vom Typ der eigenen Klasse: rekursive Beziehung

   public Knoten(Patient daten) {
      this.daten = daten;
      nachfolger = null;        // Ein neuer Knoten hat noch keinen Nachfolger.
   }

   public Patient getDaten() {
      return daten;
   }

   public Knoten getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }
}

/**
 * Die Daten einer Patientin oder eines Patienten.
 * Muss nicht verändert werden.
 */
public class Patient {
   private String name;
   private String beschwerden;

   public Patient(String name, String beschwerden) {
      this.name = name;
      this.beschwerden = beschwerden;
   }

   public String getName() {
      return name;
   }

   public String getBeschwerden() {
      return beschwerden;
   }
}

/**
 * Ein Interface legt fest, welche Methoden jede Wartezimmer-Klasse haben muss.
 * So kann das Hauptprogramm alle Varianten gleich benutzen (mehr dazu in 1.2).
 */
public interface Wartezimmer {
   boolean add(Patient p);   // hinten anstellen, true bei Erfolg
   Patient poll();           // vorne herausholen, null wenn niemand wartet
   void ausgeben();          // alle Wartenden der Reihe nach ausgeben
}

/**
 * Variante 1: Array. Neue kommen auf den ersten freien Platz,
 * aufgerufen wird der erste belegte Platz.
 */
public class WartezimmerSuchen implements Wartezimmer {
   private Patient[] plaetze;

   public WartezimmerSuchen(int kapazitaet) {
      plaetze = new Patient[kapazitaet];
   }

   public boolean add(Patient p) {
      for (int i = 0; i < plaetze.length; i++) {
         if (plaetze[i] == null) {
            plaetze[i] = p;
            return true;
         }
      }
      println("Kein Platz mehr für " + p.getName() + "!");
      return false;
   }

   public Patient poll() {
      for (int i = 0; i < plaetze.length; i++) {
         if (plaetze[i] != null) {
            Patient p = plaetze[i];
            plaetze[i] = null;
            return p;
         }
      }
      println("Niemand wartet.");
      return null;
   }

   public void ausgeben() {
      for (int i = 0; i < plaetze.length; i++) {
         if (plaetze[i] != null) {
            println("  Platz " + i + ": " + plaetze[i].getName());
         } else {
            println("  Platz " + i + ": -");
         }
      }
   }
}

/**
 * Variante 2: Array wie Variante 1, aber eine Aufrufnummer
 * merkt sich, welcher Platz als Nächstes dran ist.
 */
public class WartezimmerNummer implements Wartezimmer {
   private Patient[] plaetze;
   private int naechster = 0;   // Platz, der als Nächstes aufgerufen wird

   public WartezimmerNummer(int kapazitaet) {
      plaetze = new Patient[kapazitaet];
   }

   public boolean add(Patient p) {
      for (int i = 0; i < plaetze.length; i++) {
         if (plaetze[i] == null) {
            plaetze[i] = p;
            return true;
         }
      }
      println("Kein Platz mehr für " + p.getName() + "!");
      return false;
   }

   public Patient poll() {
      Patient p = plaetze[naechster];
      if (p == null) {
         println("Niemand wartet.");
         return null;
      }
      plaetze[naechster] = null;
      naechster++;
      return p;
   }

   public void ausgeben() {
      for (int i = 0; i < plaetze.length; i++) {
         String zeile = "  Platz " + i + ": ";
         if (plaetze[i] != null) {
            zeile = zeile + plaetze[i].getName();
         } else {
            zeile = zeile + "-";
         }
         if (i == naechster) {
            zeile = zeile + "   <- nächster";
         }
         println(zeile);
      }
   }
}

/**
 * Variante 3: Array. Nach jedem Aufruf rücken alle einen Platz nach vorne.
 */
public class WartezimmerAufruecken implements Wartezimmer {
   private Patient[] plaetze;
   private int anzahl = 0;      // so viele Plätze sind belegt

   public WartezimmerAufruecken(int kapazitaet) {
      plaetze = new Patient[kapazitaet];
   }

   public boolean add(Patient p) {
      if (anzahl < plaetze.length) {
         plaetze[anzahl] = p;
         anzahl++;
         return true;
      }
      println("Kein Platz mehr für " + p.getName() + "!");
      return false;
   }

   public Patient poll() {
      if (anzahl == 0) {
         println("Niemand wartet.");
         return null;
      }
      Patient p = plaetze[0];
      for (int i = 0; i < anzahl - 1; i++) {   // alle rücken einen Platz auf
         plaetze[i] = plaetze[i + 1];
      }
      anzahl--;
      plaetze[anzahl] = null;
      println("  (" + anzahl + " Mal verschoben)");
      return p;
   }

   public void ausgeben() {
      for (int i = 0; i < plaetze.length; i++) {
         if (plaetze[i] != null) {
            println("  Platz " + i + ": " + plaetze[i].getName());
         } else {
            println("  Platz " + i + ": -");
         }
      }
   }
}
